  fun ms' => exists (id : Z) (t0 t1 t2 a6 a7 t3 t4 t5 t6 : word) m' (sj' tb' : list word) (junk2 : list byte),
    ms' = MS (mkR (Z_to_bv 64 0x52614) (Z_to_bv 64 (bv_unsigned sp + -2128)) gp tp t0 t1 t2
