                  (Z_to_bv 64 0xb45f0) (Z_to_bv 64 (t + 80)) (Z_to_bv 64 (t + 208)) (Z_to_bv 64 (bv_unsigned sp + -2128))
                  (Z_to_bv 64 hm) (Z_to_bv 64 n) a6 a7
